    <script>
        let originalData = [];
        let dataCSV = [];
        let displayedIndex = -1;

        function parseAndShuffleCSV(csv) {
            let data = Papa.parse(csv, {
                header: true,
                skipEmptyLines: true,
                delimiter: ';'
            }).data;

            // Simpan data asli sebelum diacak
            originalData = JSON.parse(JSON.stringify(data));
            console.log(originalData)

            // Acak urutan data
            for (let i = data.length - 1; i > 0; i--) {
                let j = Math.floor(Math.random() * (i + 1));
                let temp = data[i];
                data[i] = data[j];
                data[j] = temp;
            }

            return data;
        }

        fetch('data.csv')
            .then(response => response.text())
            .then(csv => {
                dataCSV = parseAndShuffleCSV(csv);
                tampilkanBeritaSelanjutnya();
                tampilkanJumlahBelumDilabeli();
            });

        function tampilkanBeritaSelanjutnya() {
            let nextIndex = displayedIndex;
            do {
                nextIndex = (nextIndex + 1) % dataCSV.length;
            } while (nextIndex !== displayedIndex && dataCSV[nextIndex].Label);
            if (nextIndex === displayedIndex) { 
                document.getElementById('judulBerita').style.display = 'none';
                document.getElementById('isiBerita').style.display = 'none';
                document.getElementById('jumlahBelumDilabeli').style.display = 'none';
                document.querySelector('.button-container').style.display = 'none';
                document.getElementById('allDone').style.display = 'block';
                return;
            }
            displayedIndex = nextIndex;
            document.getElementById('judulBerita').innerText = dataCSV[displayedIndex].Judul;
            document.getElementById('isiBerita').innerText = dataCSV[displayedIndex].Isi_Berita;
        }

        function labelBerita(label) {
            dataCSV[displayedIndex].Label = label;
            const originalIndex = originalData.findIndex(berita => berita.Judul === dataCSV[displayedIndex].Judul);
            originalData[originalIndex].Label = label;
            tampilkanBeritaSelanjutnya();
            tampilkanJumlahBelumDilabeli();
        }

        function tampilkanJumlahBelumDilabeli() {
            const jumlahBelumDilabeli = dataCSV.filter(berita => !berita.Label).length;
            document.getElementById('jumlahBelumDilabeli').innerText = 'Belum Dilabeli: ' + jumlahBelumDilabeli;
        }

        function JSONToCSV(jsonData, delimiter = ';') {
            if (!jsonData || jsonData.length === 0) {
                return '';
            }

            let keys = Object.keys(jsonData[0]);
            let csvContent = '';

            csvContent += keys.join(delimiter) + '\n';

            jsonData.forEach(row => {
                let rowData = [];
                keys.forEach(key => {
                    rowData.push(row[key]);
                });
                csvContent += rowData.join(delimiter) + '\n';
            });

            return csvContent;
        }

        function escapeHashSymbol(jsonData) {
            return JSON.parse(JSON.stringify(jsonData).replace(/#/g, 'hashtag'));
